/**
 * CloudWatch Synthetics canary — API health check
 *
 * Runs every 5 minutes, hits the visitor counter endpoint, and asserts:
 *   1. HTTP 200 response
 *   2. Body contains a numeric visitor_count field
 *
 * On failure the canary emits a SuccessPercent < 100 metric which triggers
 * the cloudwatch_sns alarm that pages the on-call email subscriber.
 */
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');
const https = require('https');

const checkVisitorAPI = async () => {
  const url = process.env.API_URL;

  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new Error(`Expected HTTP 200 but got ${res.statusCode}. Body: ${body}`));
          return;
        }
        let json;
        try {
          json = JSON.parse(body);
        } catch (e) {
          reject(new Error(`Response body is not valid JSON: ${body}`));
          return;
        }
        if (typeof json.visitor_count !== 'number') {
          reject(new Error(`visitor_count missing or not a number. Got: ${JSON.stringify(json)}`));
          return;
        }
        log.info(`API healthy. visitor_count=${json.visitor_count}`);
        resolve();
      });
    }).on('error', (err) => {
      reject(new Error(`HTTPS request failed: ${err.message}`));
    });
  });
};

exports.handler = async () => {
  return synthetics.executeStep('checkVisitorAPI', checkVisitorAPI);
};
